package pipedrive

import (
	"context"
	"net/http"
)

type RequestEditorFunc func(ctx context.Context, req *http.Request) error

type RequestOption func(*requestOptions)

type requestOptions struct {
	headers map[string]string
	editors []RequestEditorFunc

	noRetry bool

	retryPolicy       *RetryPolicy
	responseSizeLimit responseSizeLimitOption
}

func WithHeader(key, value string) RequestOption {
	return func(o *requestOptions) {
		if o.headers == nil {
			o.headers = make(map[string]string)
		}
		o.headers[key] = value
	}
}

func WithRequestEditor(fn RequestEditorFunc) RequestOption {
	return func(o *requestOptions) {
		if fn == nil {
			return
		}
		o.editors = append(o.editors, fn)
	}
}

func WithNoRetry() RequestOption {
	return func(o *requestOptions) {
		o.noRetry = true
	}
}

func WithRetryPolicy(policy RetryPolicy) RequestOption {
	return func(o *requestOptions) {
		o.retryPolicy = &policy
	}
}

func WithResponseSizeLimit(limit int64) RequestOption {
	return func(o *requestOptions) {
		o.responseSizeLimit = responseSizeLimitOption{
			set:   true,
			limit: limit,
		}
	}
}

func WithNoResponseSizeLimit() RequestOption {
	return func(o *requestOptions) {
		o.responseSizeLimit = responseSizeLimitOption{
			set:       true,
			unlimited: true,
		}
	}
}

func ApplyRequestOptions(ctx context.Context, opts ...RequestOption) (context.Context, []RequestEditorFunc) {
	if ctx == nil {
		ctx = context.Background()
	}

	var o requestOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt(&o)
	}

	if o.noRetry {
		ctx = withNoRetry(ctx)
	}
	if o.retryPolicy != nil {
		ctx = withRetryPolicy(ctx, *o.retryPolicy)
	}
	if o.responseSizeLimit.set {
		ctx = withResponseSizeLimit(ctx, o.responseSizeLimit)
	}

	editors := make([]RequestEditorFunc, 0, len(o.editors)+1)
	if len(o.headers) > 0 {
		headers := make(map[string]string, len(o.headers))
		for k, v := range o.headers {
			headers[k] = v
		}
		editors = append(editors, func(_ context.Context, req *http.Request) error {
			for k, v := range headers {
				req.Header.Set(k, v)
			}
			return nil
		})
	}
	editors = append(editors, o.editors...)

	return ctx, editors
}

package pipedrive

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

type RawClient struct {
	baseURL    *url.URL
	httpClient *http.Client
}

func NewRawClient(baseURL string, httpClient *http.Client) (*RawClient, error) {
	if httpClient == nil {
		httpClient = http.DefaultClient
	}
	u, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("parse base url: %w", err)
	}
	if u.Scheme == "" || u.Host == "" {
		return nil, errors.New("base url must include scheme and host")
	}
	u.Path = strings.TrimSuffix(u.Path, "/")

	return &RawClient{
		baseURL:    u,
		httpClient: httpClient,
	}, nil
}

func (c *RawClient) Do(ctx context.Context, method, path string, query url.Values, body any, out any, opts ...RequestOption) error {
	if c == nil {
		return errors.New("nil RawClient")
	}

	ctx, editors := ApplyRequestOptions(ctx, opts...)

	u := *c.baseURL
	u.Path = strings.TrimSuffix(u.Path, "/") + "/" + strings.TrimPrefix(path, "/")
	if query != nil {
		q := u.Query()
		for k, vs := range query {
			for _, v := range vs {
				q.Add(k, v)
			}
		}
		u.RawQuery = q.Encode()
	}

	var reqBody io.Reader
	if body != nil {
		switch b := body.(type) {
		case io.Reader:
			reqBody = b
		default:
			buf, err := json.Marshal(b)
			if err != nil {
				return fmt.Errorf("encode json body: %w", err)
			}
			reqBody = bytes.NewReader(buf)
		}
	}

	req, err := http.NewRequestWithContext(ctx, method, u.String(), reqBody)
	if err != nil {
		return fmt.Errorf("build request: %w", err)
	}

	req.Header.Set("Accept", "application/json")
	if body != nil {
		if _, ok := body.(io.Reader); !ok {
			req.Header.Set("Content-Type", "application/json")
		}
	}

	for _, editor := range editors {
		if editor == nil {
			continue
		}
		if err := editor(ctx, req); err != nil {
			return err
		}
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("read response: %w", err)
	}

	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		if resp.StatusCode == http.StatusTooManyRequests {
			return RateLimitErrorFromResponse(resp, respBody, time.Now())
		}
		return APIErrorFromResponse(resp, respBody)
	}

	if out == nil || len(respBody) == 0 {
		return nil
	}
	if err := json.Unmarshal(respBody, out); err != nil {
		return fmt.Errorf("decode response json: %w", err)
	}
	return nil
}

